export const QUOTES_EN = [
  { id: "animo-001", category: "animo", text: "You do not need to solve your whole life today; you need one step that stays true to you." },
  { id: "animo-002", category: "animo", text: "The most reliable motivation appears after you begin, not before." },
  { id: "animo-003", category: "animo", text: "Even when you move slowly, you are still on the side of those who refuse to give up." },
  { id: "animo-004", category: "animo", text: "Use the energy you have; consistency has room for imperfect days too." },
  { id: "animo-005", category: "animo", text: "A modest day can still leave one corner of your life better than it found it." },
  { id: "animo-006", category: "animo", text: "Do not wait to feel invincible before moving; move to remind yourself that you can." },
  { id: "animo-007", category: "animo", text: "Your next attempt does not have to carry the weight of every attempt before it." },
  { id: "animo-008", category: "animo", text: "One honest action beats a brilliant promise that never begins." },
  { id: "animo-009", category: "animo", text: "If you doubt yourself today, do something clear enough to make doubt step aside." },
  { id: "animo-010", category: "animo", text: "Encouragement does not always shout; sometimes it simply whispers that you should keep going." },
  { id: "animo-011", category: "animo", text: "Some days do not ask for greatness; they ask for presence." },
  { id: "animo-012", category: "animo", text: "Begin again with what you learned, without turning the restart into a performance." },
  { id: "animo-013", category: "animo", text: "You do not have to prove everything today; just do not abandon yourself." },
  { id: "animo-014", category: "animo", text: "Hard things feel lighter when you break them down into one manageable action." },
  { id: "animo-015", category: "animo", text: "Your progress deserves respect even when nobody is watching." },
  { id: "animo-016", category: "animo", text: "Start with the part of you that still believes another attempt is worth making today." },
  { id: "animo-017", category: "animo", text: "A tired step can still carry you toward a life that feels more like your own." },
  { id: "animo-018", category: "animo", text: "You are allowed to rebuild momentum without pretending the difficult days never happened." },
  { id: "animo-019", category: "animo", text: "Give this morning one honest chance before deciding what the whole day will become." },
  { id: "animo-020", category: "animo", text: "The part of you that kept going quietly deserves a say in what happens next." },
  { id: "animo-021", category: "animo", text: "Finish one small task today and give yourself a concrete reason to feel encouraged." },
  { id: "animo-022", category: "animo", text: "A difficult season can change your pace without taking away your direction." },
  { id: "animo-023", category: "animo", text: "Showing up before confidence arrives is a quiet kind of courage." },
  { id: "animo-024", category: "animo", text: "Let the next ten minutes be kinder and more deliberate than the ten before them." },
  { id: "animo-025", category: "animo", text: "You do not need a dramatic comeback; a quiet return to yourself is enough for today." },
  { id: "animo-026", category: "animo", text: "Keep one promise to yourself today and let that be evidence that change is underway." },
  { id: "animo-027", category: "animo", text: "What remains unfinished is not proof of failure; it is simply where your next step can begin." },
  { id: "animo-028", category: "animo", text: "Some strength returns only after you stop demanding that it arrive all at once." },
  { id: "animo-029", category: "animo", text: "Choose the smallest action that makes tomorrow less heavy, then give it your full care." },
  { id: "animo-030", category: "animo", text: "Your hope does not have to be loud; it only needs enough room to influence one decision." },
  { id: "animo-031", category: "animo", text: "A rough morning does not own the afternoon; choose one useful thing and begin there." },
  { id: "animo-032", category: "animo", text: "Keep faith with the work while its early results are still too small to see." },
  { id: "animo-033", category: "animo", text: "When the whole road feels heavy, carry only the next piece of it." },
  { id: "animo-034", category: "animo", text: "Today's effort can be quiet and real; it does not need an audience to count." },
  { id: "animo-035", category: "animo", text: "A missed chance is not the last door; look carefully at what is still open." },
  { id: "animo-036", category: "animo", text: "Honor the effort behind a difficult choice, even when nobody else could see its cost." },
  { id: "animo-037", category: "animo", text: "You can change the tone of this day with one kind action toward your future self." },
  { id: "animo-038", category: "animo", text: "If the plan fell apart, keep the purpose and choose a simpler route." },
  { id: "animo-039", category: "animo", text: "There is still value in what you can offer today, even when it is less than you hoped." },
  { id: "animo-040", category: "animo", text: "When enthusiasm is absent, ask someone you trust to join you for the first part." },
  { id: "animo-041", category: "animo", text: "Your effort is not wasted just because the lesson arrived before the reward." },
  { id: "animo-042", category: "animo", text: "Make one decision today that leaves you a little more room to breathe tomorrow." },
  { id: "animo-043", category: "animo", text: "The courage to try again can look ordinary from the outside and still change your direction." },
  { id: "animo-044", category: "animo", text: "You have handled uncertain days before; meet this one with the skills you have now." },
  { id: "animo-045", category: "animo", text: "Do not wait for perfect conditions to care for something that matters to you." },
  { id: "animo-046", category: "animo", text: "A better chapter can begin with a choice so small that only you notice it." },
  { id: "animo-047", category: "animo", text: "Use the fact that you care as a reason to act, not another reason to worry." },
  { id: "animo-048", category: "animo", text: "Notice what became easier this year; yesterday's effort may already be helping you today." },
  { id: "animo-049", category: "animo", text: "Look for the part of the problem that responds to your hands, your voice, or your next call." },
  { id: "animo-050", category: "animo", text: "What you begin with uncertainty can still become something you are proud to have finished." },
  { id: "animo-051", category: "animo", text: "Treat a disappointing result as new information, then choose what deserves another attempt." },
  { id: "animo-052", category: "animo", text: "Make a beginning that fits who you are today, not the energy you expected to have." },
  { id: "animo-053", category: "animo", text: "Choose a task small enough to finish and meaningful enough to restore a little confidence." },
  { id: "animo-054", category: "animo", text: "An honest adjustment can keep a goal alive longer than stubbornly following the original plan." },
  { id: "animo-055", category: "animo", text: "Send the application, ask the question, or open the document; let reality answer the doubt." },
  { id: "animo-056", category: "animo", text: "A week of quiet choices may reveal progress that one day alone could not show you." },
  { id: "animo-057", category: "animo", text: "Reach out to the person whose encouragement helps you see the situation more clearly." },
  { id: "animo-058", category: "animo", text: "When confidence is scarce, let preparation carry part of the weight." },
  { id: "animo-059", category: "animo", text: "Be patient with the part of you that is still learning how to handle what comes next." },
  { id: "animo-060", category: "animo", text: "Before calling the day lost, do one thing that will make coming home to yourself easier." },
  { id: "foco-001", category: "foco", text: "The day changes when you decide what no longer deserves your attention." },
  { id: "foco-002", category: "foco", text: "One clear priority is worth more than a huge anxiety-driven list." },
  { id: "foco-003", category: "foco", text: "Return to what matters before the urgent steals your morning." },
  { id: "foco-004", category: "foco", text: "When every task asks to be first, choose the one whose absence would matter tomorrow." },
  { id: "foco-005", category: "foco", text: "Finishing one small thing can create more order than opening ten new fronts." },
  { id: "foco-006", category: "foco", text: "Your attention is an investment; place it where you want something to grow." },
  { id: "foco-007", category: "foco", text: "Fewer open tabs, less mental noise, and more meaningful progress." },
  { id: "foco-008", category: "foco", text: "You do not need more hours; you need fewer leaks in your attention." },
  { id: "foco-009", category: "foco", text: "First do what restores direction, not what merely creates movement." },
  { id: "foco-010", category: "foco", text: "Focus is not tension; it is staying faithful to one thing for a while." },
  { id: "foco-011", category: "foco", text: "Whenever you say yes to everything, your goal hears a no." },
  { id: "foco-012", category: "foco", text: "Give your day clear boundaries: one task, one time block, one decision." },
  { id: "foco-013", category: "foco", text: "Do not confuse being available with moving forward." },
  { id: "foco-014", category: "foco", text: "Clarity usually arrives after removing, not after adding." },
  { id: "foco-015", category: "foco", text: "What matters rarely competes with noise; it waits for you to choose it." },
  { id: "foco-016", category: "foco", text: "Protect the hour that can change your day from the messages that merely interrupt it." },
  { id: "foco-017", category: "foco", text: "A clear no can return more attention to your life than another clever schedule." },
  { id: "foco-018", category: "foco", text: "Before adding a new task, ask which unfinished one is still occupying the room." },
  { id: "foco-019", category: "foco", text: "Leave enough silence around the work for your best thinking to find its way in." },
  { id: "foco-020", category: "foco", text: "Decide what progress means for this hour, not for your entire life." },
  { id: "foco-021", category: "foco", text: "Attention scattered across five good ideas may finish none of them." },
  { id: "foco-022", category: "foco", text: "Schedule the important task when your energy is strongest, not when the calendar looks neat." },
  { id: "foco-023", category: "foco", text: "You can answer later; the thought in front of you may not return in the same shape." },
  { id: "foco-024", category: "foco", text: "One deliberate hour can protect more of your day than a dozen hurried ones." },
  { id: "foco-025", category: "foco", text: "Let completion, not novelty, decide where your attention goes next." },
  { id: "foco-026", category: "foco", text: "The task becomes clearer when you name the exact point where you will stop." },
  { id: "foco-027", category: "foco", text: "Close the door on one distraction before asking yourself for deeper concentration." },
  { id: "foco-028", category: "foco", text: "A short list chosen with care can hold more ambition than a crowded one." },
  { id: "foco-029", category: "foco", text: "When your mind starts wandering, return to the next visible action, not the entire plan." },
  { id: "foco-030", category: "foco", text: "Make room for depth by refusing one demand that was never truly yours." },
  { id: "foco-031", category: "foco", text: "Write down the one result that would make this hour useful, then work backward from it." },
  { id: "foco-032", category: "foco", text: "Put your phone beyond easy reach while the task still needs your full mind." },
  { id: "foco-033", category: "foco", text: "Choose the verb in the task: write, call, compare, decide, or delete." },
  { id: "foco-034", category: "foco", text: "Keep a blank page nearby for stray thoughts, so they do not take over the task at hand." },
  { id: "foco-035", category: "foco", text: "Move the most relevant file to the center of the desk and begin with the strongest evidence." },
  { id: "foco-036", category: "foco", text: "If you keep switching tasks, pause and finish the smallest open loop first." },
  { id: "foco-037", category: "foco", text: "Read the difficult paragraph twice before searching for an easier distraction." },
  { id: "foco-038", category: "foco", text: "If a thought belongs to another project, file it there instead of following it now." },
  { id: "foco-039", category: "foco", text: "Start with the question the finished work should answer." },
  { id: "foco-040", category: "foco", text: "A timer can hold the boundary while you give the work your undivided attention." },
  { id: "foco-041", category: "foco", text: "When the task feels blurry, rewrite it as a visible action with a clear object." },
  { id: "foco-042", category: "foco", text: "Check whether the meeting needs you before giving it the best hour of your day." },
  { id: "foco-043", category: "foco", text: "Place only one project's materials in view and put the rest away." },
  { id: "foco-044", category: "foco", text: "Spend less time arranging the list and more time reducing it." },
  { id: "foco-045", category: "foco", text: "Write the central question at the top of the page so each new detail has to earn its place." },
  { id: "foco-046", category: "foco", text: "Set a stopping point before perfection quietly turns one task into the whole day." },
  { id: "foco-047", category: "foco", text: "If two priorities compete, ask which one makes the other easier or unnecessary." },
  { id: "foco-048", category: "foco", text: "Make the next action specific enough that your hands know where to begin." },
  { id: "foco-049", category: "foco", text: "Protect the middle of the task; that is often where novelty fades and useful work begins." },
  { id: "foco-050", category: "foco", text: "Before opening another source, explain what the information you already have actually says." },
  { id: "foco-051", category: "foco", text: "Reserve a short window for replies so they stop dividing every other hour." },
  { id: "foco-052", category: "foco", text: "When you lose your place, reread the last decision instead of restarting the whole plan." },
  { id: "foco-053", category: "foco", text: "A closed door, a cleared desk, and one stated goal can be enough structure for good work." },
  { id: "foco-054", category: "foco", text: "Use your notes to return quickly, not to postpone the difficult part of thinking." },
  { id: "foco-055", category: "foco", text: "Decide which detail matters to the outcome and let the decorative ones remain unfinished." },
  { id: "foco-056", category: "foco", text: "Work in the order the problem requires, not the order the easy parts suggest." },
  { id: "foco-057", category: "foco", text: "Turn off one alert and notice how much longer a complete thought can stay with you." },
  { id: "foco-058", category: "foco", text: "A useful draft answers the main question before it improves every sentence." },
  { id: "foco-059", category: "foco", text: "Name the interruption, park it on paper, and return to the exact line you left." },
  { id: "foco-060", category: "foco", text: "End the session by writing the next step, so tomorrow begins with direction instead of recall." },
  { id: "calma-001", category: "calma", text: "Breathe before answering; sometimes peace fits inside three seconds." },
  { id: "calma-002", category: "calma", text: "Not everything you feel requires an immediate reaction." },
  { id: "calma-003", category: "calma", text: "Turn down the volume of the day until you can hear yourself again." },
  { id: "calma-004", category: "calma", text: "A slower pace can reveal the part of the day your hurry kept walking past." },
  { id: "calma-005", category: "calma", text: "Your body is not an obstacle; it is where your life happens." },
  { id: "calma-006", category: "calma", text: "For a moment, release what you cannot fix from where you are now." },
  { id: "calma-007", category: "calma", text: "A brief pause can protect you from a decision made while tired." },
  { id: "calma-008", category: "calma", text: "Calm does not always arrive on its own; sometimes you must make room for it." },
  { id: "calma-009", category: "calma", text: "You do not need to win the argument with your mind; you can let it pass." },
  { id: "calma-010", category: "calma", text: "Today you can choose gentleness without giving up firmness." },
  { id: "calma-011", category: "calma", text: "Heavy things are easier to face when you sit, breathe, and take your time." },
  { id: "calma-012", category: "calma", text: "Do not confuse silence with emptiness; sometimes silence is repair." },
  { id: "calma-013", category: "calma", text: "If everything feels too much, begin by returning to your breath." },
  { id: "calma-014", category: "calma", text: "Serenity does not deny the problem; it keeps the problem from ruling you." },
  { id: "calma-015", category: "calma", text: "Give yourself permission not to accelerate when your life needs care." },
  { id: "calma-016", category: "calma", text: "Let your shoulders receive the message that nothing must be solved in this breath." },
  { id: "calma-017", category: "calma", text: "You can wait for the feeling to settle before deciding what it means." },
  { id: "calma-018", category: "calma", text: "Move one thing off your inner table; you do not need to hold every concern at once." },
  { id: "calma-019", category: "calma", text: "A slower answer may protect both the truth and the person who needs to hear it." },
  { id: "calma-020", category: "calma", text: "Notice what is steady: the floor, the chair, the breath arriving without instructions." },
  { id: "calma-021", category: "calma", text: "Give the noise a boundary instead of asking yourself to become louder than it." },
  { id: "calma-022", category: "calma", text: "The day can remain unfinished while you take a moment to become present again." },
  { id: "calma-023", category: "calma", text: "Not every uneasy thought deserves a chair at the center of the room." },
  { id: "calma-024", category: "calma", text: "Rest your attention on something ordinary until your mind stops running ahead." },
  { id: "calma-025", category: "calma", text: "You are not falling behind when you pause long enough to choose your next step well." },
  { id: "calma-026", category: "calma", text: "Release the version of this conversation that has only happened in your imagination." },
  { id: "calma-027", category: "calma", text: "There is no need to turn a difficult minute into a prediction about the whole week." },
  { id: "calma-028", category: "calma", text: "Let quiet be a place where you gather yourself, not another standard you must meet." },
  { id: "calma-029", category: "calma", text: "Before searching for another explanation, notice one steady and reassuring detail around you." },
  { id: "calma-030", category: "calma", text: "Make this moment smaller: this room, this breath, this one thing you can gently do." },
  { id: "calma-031", category: "calma", text: "Name three things that are certain today before giving more space to everything uncertain." },
  { id: "calma-032", category: "calma", text: "Wait until your voice softens before answering a question that matters." },
  { id: "calma-033", category: "calma", text: "Open the window, notice the temperature, and return to the day you are actually living." },
  { id: "calma-034", category: "calma", text: "Listen to one ordinary sound until the rush begins to loosen." },
  { id: "calma-035", category: "calma", text: "A concern written down no longer has to circle your mind just to be remembered." },
  { id: "calma-036", category: "calma", text: "You can leave the answer for morning and give the night back its quiet." },
  { id: "calma-037", category: "calma", text: "Unclench your hands; they do not need to carry a problem that belongs to tomorrow." },
  { id: "calma-038", category: "calma", text: "Find a quieter place before trying to force a quieter mind." },
  { id: "calma-039", category: "calma", text: "Warm water, clean clothes, and an unhurried meal can make the evening feel gentler." },
  { id: "calma-040", category: "calma", text: "Not knowing yet is uncomfortable, but it does not require a hurried conclusion." },
  { id: "calma-041", category: "calma", text: "Lower the light and the pace; the day does not need to end at full volume." },
  { id: "calma-042", category: "calma", text: "Give the feeling a name without turning it into an instruction." },
  { id: "calma-043", category: "calma", text: "Take the longer route home if those extra minutes help you arrive with a clearer mind." },
  { id: "calma-044", category: "calma", text: "The conversation can wait until you can hear more than your own urgency." },
  { id: "calma-045", category: "calma", text: "Notice five things that are not asking anything from you right now." },
  { id: "calma-046", category: "calma", text: "Use a small routine to tell your mind that work has ended for today." },
  { id: "calma-047", category: "calma", text: "You may understand the situation better after food, rest, and a little distance." },
  { id: "calma-048", category: "calma", text: "Read the message once, then place the phone down before inventing what it might mean." },
  { id: "calma-049", category: "calma", text: "Make room between the event and the story you are about to build around it." },
  { id: "calma-050", category: "calma", text: "Wait for the kettle to boil without filling the minute with another demand." },
  { id: "calma-051", category: "calma", text: "A few minutes without input can help you notice what was already inside the day." },
  { id: "calma-052", category: "calma", text: "Move at the speed that lets you notice where you are placing your attention." },
  { id: "calma-053", category: "calma", text: "Fold one piece of clothing or wash one cup, and let the simple action slow the moment down." },
  { id: "calma-054", category: "calma", text: "Ask whether this thought needs attention now, later, or not at all." },
  { id: "calma-055", category: "calma", text: "Allow the music to end before deciding what should fill the silence next." },
  { id: "calma-056", category: "calma", text: "Step outside for one minute and give the horizon more space than the screen." },
  { id: "calma-057", category: "calma", text: "A gentler schedule begins by admitting how much the day can reasonably hold." },
  { id: "calma-058", category: "calma", text: "Set the problem beside you for a while; carrying it constantly is not the same as solving it." },
  { id: "calma-059", category: "calma", text: "The next hour does not need a perfect plan; it needs a pace you can inhabit." },
  { id: "calma-060", category: "calma", text: "Finish the sip before reaching for the next task; this minute can remain simple." },
  { id: "disciplina-001", category: "disciplina", text: "Discipline means listening to your future when your present starts negotiating." },
  { id: "disciplina-002", category: "disciplina", text: "You do not need constant motivation; you need an agreement with yourself." },
  { id: "disciplina-003", category: "disciplina", text: "Make it small, but do it today; that is how you train self-trust." },
  { id: "disciplina-004", category: "disciplina", text: "A promise kept quietly changes more than one announced loudly." },
  { id: "disciplina-005", category: "disciplina", text: "Repeating the useful step on ordinary days gives a long project something steady to build on." },
  { id: "disciplina-006", category: "disciplina", text: "When you wait for the perfect moment, you hand control to the excuse." },
  { id: "disciplina-007", category: "disciplina", text: "Discipline does not imprison you; it frees you from always starting over." },
  { id: "disciplina-008", category: "disciplina", text: "One small commitment kept is worth more than one enormous plan abandoned." },
  { id: "disciplina-009", category: "disciplina", text: "Today, do not negotiate with the part of you that always postpones." },
  { id: "disciplina-010", category: "disciplina", text: "Consistency is a quiet form of self-respect." },
  { id: "disciplina-011", category: "disciplina", text: "Keep the basic promise even when nobody can applaud it." },
  { id: "disciplina-012", category: "disciplina", text: "Repetition turns an intention into evidence you can review and improve." },
  { id: "disciplina-013", category: "disciplina", text: "Complete the first agreed step before deciding whether the plan needs to change." },
  { id: "disciplina-014", category: "disciplina", text: "Do not chase daily intensity; build a foundation that does not break." },
  { id: "disciplina-015", category: "disciplina", text: "Each promise kept makes the next beginning feel a little less unfamiliar." },
  { id: "disciplina-016", category: "disciplina", text: "Build a routine that still works when enthusiasm has somewhere else to be." },
  { id: "disciplina-017", category: "disciplina", text: "The useful plan is the one you can follow on an ordinary Wednesday." },
  { id: "disciplina-018", category: "disciplina", text: "Keep the starting line close enough that excuses cannot hide the way to it." },
  { id: "disciplina-019", category: "disciplina", text: "Do the agreed amount, then stop with the satisfaction of having kept your word." },
  { id: "disciplina-020", category: "disciplina", text: "A boundary around your effort keeps commitment from turning into punishment." },
  { id: "disciplina-021", category: "disciplina", text: "Prepare the first action tonight so tomorrow has less room for negotiation." },
  { id: "disciplina-022", category: "disciplina", text: "Measure the return, not the interruption; coming back is the skill you are building." },
  { id: "disciplina-023", category: "disciplina", text: "Choose a minimum that protects continuity without pretending every day is equal." },
  { id: "disciplina-024", category: "disciplina", text: "Your calendar should reflect your commitment before your mood gets a vote." },
  { id: "disciplina-025", category: "disciplina", text: "Leave yourself visible proof: one finished repetition, honestly recorded." },
  { id: "disciplina-026", category: "disciplina", text: "A reliable pace is allowed to look unimpressive while it carries you forward." },
  { id: "disciplina-027", category: "disciplina", text: "Remove one decision from the routine and save your effort for doing the work." },
  { id: "disciplina-028", category: "disciplina", text: "Stop making tomorrow repay everything you postponed today; begin with one honest task." },
  { id: "disciplina-029", category: "disciplina", text: "Consistency grows when the promise is specific enough to know when it is complete." },
  { id: "disciplina-030", category: "disciplina", text: "Respect the structure that helps you act, then adjust it when life genuinely changes." },
  { id: "disciplina-031", category: "disciplina", text: "Give the work a visible deadline before it quietly expands into every available hour." },
  { id: "disciplina-032", category: "disciplina", text: "Decide which days are for practice and keep that time clear of optional errands." },
  { id: "disciplina-033", category: "disciplina", text: "Begin at the agreed time, even if the first ten minutes are not impressive." },
  { id: "disciplina-034", category: "disciplina", text: "Treat the appointment with your own work as carefully as one made with someone else." },
  { id: "disciplina-035", category: "disciplina", text: "Track what you completed, not the dramatic promises you made at the beginning." },
  { id: "disciplina-036", category: "disciplina", text: "When one method fails repeatedly, change the method while keeping the appointment." },
  { id: "disciplina-037", category: "disciplina", text: "Decide the limit of the session, then use that boundary to work with purpose." },
  { id: "disciplina-038", category: "disciplina", text: "Make the useful choice easier before asking willpower to rescue the evening." },
  { id: "disciplina-039", category: "disciplina", text: "Finish the planned set before deciding whether you feel productive." },
  { id: "disciplina-040", category: "disciplina", text: "Use a checklist for the routine parts and save your judgment for the choices that need it." },
  { id: "disciplina-041", category: "disciplina", text: "Choose a weekly rhythm that leaves room for both effort and recovery." },
  { id: "disciplina-042", category: "disciplina", text: "When you miss the morning, use the afternoon instead of waiting for a cleaner restart." },
  { id: "disciplina-043", category: "disciplina", text: "Leave the workspace ready so beginning tomorrow requires fewer acts of persuasion." },
  { id: "disciplina-044", category: "disciplina", text: "An honest record of three repetitions is more useful than a perfect streak you cannot sustain." },
  { id: "disciplina-045", category: "disciplina", text: "Define completion before you begin, so difficulty does not keep moving the finish line." },
  { id: "disciplina-046", category: "disciplina", text: "Reduce the task until resistance loses its argument, then complete that version." },
  { id: "disciplina-047", category: "disciplina", text: "Practice the difficult step separately until it stops slowing down the whole routine." },
  { id: "disciplina-048", category: "disciplina", text: "Stop at the planned point; discipline also means not turning effort into excess." },
  { id: "disciplina-049", category: "disciplina", text: "Check the process after the week ends, not after every uncomfortable hour." },
  { id: "disciplina-050", category: "disciplina", text: "Put the recurring task on the calendar before the empty space fills itself." },
  { id: "disciplina-051", category: "disciplina", text: "Do the unglamorous preparation that makes tomorrow's important work possible." },
  { id: "disciplina-052", category: "disciplina", text: "Complete the maintenance task before neglect turns it into tomorrow's emergency." },
  { id: "disciplina-053", category: "disciplina", text: "Choose tools that make the correct action obvious when your attention is tired." },
  { id: "disciplina-054", category: "disciplina", text: "A modest target completed regularly can support a larger ambition without consuming your life." },
  { id: "disciplina-055", category: "disciplina", text: "Remove the extra steps that give procrastination more places to hide." },
  { id: "disciplina-056", category: "disciplina", text: "Review the promise when your circumstances change, not simply when the work feels dull." },
  { id: "disciplina-057", category: "disciplina", text: "Complete today's portion before borrowing energy from the time reserved for rest." },
  { id: "disciplina-058", category: "disciplina", text: "If the system keeps failing, improve the setup instead of increasing the punishment." },
  { id: "disciplina-059", category: "disciplina", text: "Keep one dependable routine through a chaotic week and let the rest become optional." },
  { id: "disciplina-060", category: "disciplina", text: "Close the day by resetting one thing that will make tomorrow's start more direct." },
  { id: "autoestima-001", category: "autoestima", text: "Speak to yourself as if you must live with yourself forever, because you do." },
  { id: "autoestima-002", category: "autoestima", text: "Your worth does not rise or fall with the latest opinion." },
  { id: "autoestima-003", category: "autoestima", text: "You are not an unfinished project; you are a person still growing." },
  { id: "autoestima-004", category: "autoestima", text: "Treating yourself harshly will not help you improve faster; it will only wear you down." },
  { id: "autoestima-005", category: "autoestima", text: "You can acknowledge what is missing without denying everything you already are." },
  { id: "autoestima-006", category: "autoestima", text: "You do not need to become someone else to deserve care." },
  { id: "autoestima-007", category: "autoestima", text: "Comparison reduces a whole life to a snapshot from someone else's life." },
  { id: "autoestima-008", category: "autoestima", text: "Your rest does not need to be justified by total exhaustion." },
  { id: "autoestima-009", category: "autoestima", text: "Not every mistake deserves punishment; some only ask to be learned from." },
  { id: "autoestima-010", category: "autoestima", text: "Stay loyal to yourself even when you feel disappointed in who you are." },
  { id: "autoestima-011", category: "autoestima", text: "Do not abandon yourself to fit into a place that does not care for you." },
  { id: "autoestima-012", category: "autoestima", text: "Make one decision today in which your own voice is not the last one consulted." },
  { id: "autoestima-013", category: "autoestima", text: "Your sensitivity can offer useful information; listen to it without letting one feeling decide everything." },
  { id: "autoestima-014", category: "autoestima", text: "Stop demanding perfection before allowing yourself affection." },
  { id: "autoestima-015", category: "autoestima", text: "You are more than your productivity, even on your best days." },
  { id: "autoestima-016", category: "autoestima", text: "You can correct your course without turning yourself into the enemy." },
  { id: "autoestima-017", category: "autoestima", text: "Let your inner voice become a place where mistakes can be examined without humiliation." },
  { id: "autoestima-018", category: "autoestima", text: "The qualities you value in others are not evidence that you lack them." },
  { id: "autoestima-019", category: "autoestima", text: "You do not owe anyone a smaller version of yourself to make the room feel easier." },
  { id: "autoestima-020", category: "autoestima", text: "Your needs remain real even when you cannot explain them perfectly." },
  { id: "autoestima-021", category: "autoestima", text: "Notice whose standards are speaking before you decide you are not enough." },
  { id: "autoestima-022", category: "autoestima", text: "You can be proud of how you handled something and still wish it had been different." },
  { id: "autoestima-023", category: "autoestima", text: "Offer yourself the patience you naturally give to someone learning a difficult skill." },
  { id: "autoestima-024", category: "autoestima", text: "A boundary is not evidence that you care less; sometimes it proves you include yourself." },
  { id: "autoestima-025", category: "autoestima", text: "Do not make your most insecure hour responsible for defining your whole character." },
  { id: "autoestima-026", category: "autoestima", text: "You are allowed to enjoy what you have built before deciding how to improve it." },
  { id: "autoestima-027", category: "autoestima", text: "Treat your limits as information, not as a verdict on your worth." },
  { id: "autoestima-028", category: "autoestima", text: "Notice which places let you speak freely without turning your dignity into an apology." },
  { id: "autoestima-029", category: "autoestima", text: "Speak one true thing about yourself that has nothing to do with achievement." },
  { id: "autoestima-030", category: "autoestima", text: "You can outgrow an old judgment without proving that the person who made it was wrong." },
  { id: "autoestima-031", category: "autoestima", text: "Keep a small record of what you handled well; doubt rarely keeps an accurate archive." },
  { id: "autoestima-032", category: "autoestima", text: "Let a compliment land without immediately explaining why you might not deserve it." },
  { id: "autoestima-033", category: "autoestima", text: "Your unfinished edges do not cancel the parts of you that already feel solid." },
  { id: "autoestima-034", category: "autoestima", text: "Choose clothes, plans, and company that let you inhabit your life without performing." },
  { id: "autoestima-035", category: "autoestima", text: "Notice the moment self-correction turns into self-attack, and stop the conversation there." },
  { id: "autoestima-036", category: "autoestima", text: "One awkward moment is too little evidence to rewrite your whole opinion of yourself." },
  { id: "autoestima-037", category: "autoestima", text: "Give your preferences room to exist before asking whether everyone else approves." },
  { id: "autoestima-038", category: "autoestima", text: "The care you offer others is also a skill you are allowed to practice on yourself." },
  { id: "autoestima-039", category: "autoestima", text: "Apologize for the harm you caused, not for the space your honest presence occupies." },
  { id: "autoestima-040", category: "autoestima", text: "A slower answer can be more respectful to yourself than an immediate, unwanted yes." },
  { id: "autoestima-041", category: "autoestima", text: "Read your old plans with kindness; they were written with the information you had then." },
  { id: "autoestima-042", category: "autoestima", text: "Make one choice today because it suits you, not because it will be easy to explain." },
  { id: "autoestima-043", category: "autoestima", text: "You are allowed to be new at something without turning inexperience into a character flaw." },
  { id: "autoestima-044", category: "autoestima", text: "Separate what needs improvement from what simply fails to please a particular person." },
  { id: "autoestima-045", category: "autoestima", text: "Protect time for yourself with the same care you give to the work that depends on you." },
  { id: "autoestima-046", category: "autoestima", text: "Allow a photograph of yourself to be a memory, not an inspection." },
  { id: "autoestima-047", category: "autoestima", text: "When you change your mind thoughtfully, you are responding to life rather than betraying yourself." },
  { id: "autoestima-048", category: "autoestima", text: "Do not let someone else's urgency decide how much of yourself you must give away." },
  { id: "autoestima-049", category: "autoestima", text: "There is no prize for being the last person to notice that you need gentleness." },
  { id: "autoestima-050", category: "autoestima", text: "Take up one ordinary pleasure without making productivity its admission price." },
  { id: "autoestima-051", category: "autoestima", text: "An honest no can protect the part of you that an automatic yes keeps overlooking." },
  { id: "autoestima-052", category: "autoestima", text: "Speak about your strengths with the same accuracy you use when listing your faults." },
  { id: "autoestima-053", category: "autoestima", text: "You can miss who you used to be without treating who you are now as a disappointment." },
  { id: "autoestima-054", category: "autoestima", text: "A day spent learning your limits can still be a day used wisely." },
  { id: "autoestima-055", category: "autoestima", text: "Ask whether the rule you broke was fair before using it as evidence against yourself." },
  { id: "autoestima-056", category: "autoestima", text: "Let your body be a place you live with attention, not a problem you monitor all day." },
  { id: "autoestima-057", category: "autoestima", text: "Receiving help does not erase the effort you made before someone arrived." },
  { id: "autoestima-058", category: "autoestima", text: "The person you are becoming needs encouragement as much as honest feedback." },
  { id: "autoestima-059", category: "autoestima", text: "Protect a little privacy; not every meaningful part of you needs an audience." },
  { id: "autoestima-060", category: "autoestima", text: "End one self-criticism by naming the next useful action instead." },
  { id: "gratitud-001", category: "gratitud", text: "Gratitude does not deny what is hard; it remembers that not everything is lost." },
  { id: "gratitud-002", category: "gratitud", text: "Some days are saved by taking the time to notice one good thing." },
  { id: "gratitud-003", category: "gratitud", text: "Ordinary things deserve ceremony too: water, light, shelter, someone who answers." },
  { id: "gratitud-004", category: "gratitud", text: "Gratitude helps you see what is already enough." },
  { id: "gratitud-005", category: "gratitud", text: "Notice what already supports you before chasing what is missing." },
  { id: "gratitud-006", category: "gratitud", text: "Some gifts look like an uneventful afternoon in which your body finally feels safe." },
  { id: "gratitud-007", category: "gratitud", text: "Sometimes abundance begins when you stop looking only at what you lack." },
  { id: "gratitud-008", category: "gratitud", text: "Today, be grateful for something you once requested in silence." },
  { id: "gratitud-009", category: "gratitud", text: "Life does not need to be perfect to contain precious parts." },
  { id: "gratitud-010", category: "gratitud", text: "When you notice small comforts, the day gains details that hurry would have missed." },
  { id: "gratitud-011", category: "gratitud", text: "There is stability in simple things you almost never celebrate." },
  { id: "gratitud-012", category: "gratitud", text: "Gratitude also means pausing long enough to receive." },
  { id: "gratitud-013", category: "gratitud", text: "Do not wait for a great achievement to notice the beauty of the path." },
  { id: "gratitud-014", category: "gratitud", text: "What feels ordinary today may once have been a dream." },
  { id: "gratitud-015", category: "gratitud", text: "Gratitude does not change every fact, but it changes your perspective on them." },
  { id: "gratitud-016", category: "gratitud", text: "Notice the quiet systems holding your day together before you call it ordinary." },
  { id: "gratitud-017", category: "gratitud", text: "Thank the version of you who completed the small task you now take for granted." },
  { id: "gratitud-018", category: "gratitud", text: "Some goodness is easy to miss because it arrives faithfully instead of dramatically." },
  { id: "gratitud-019", category: "gratitud", text: "Let one familiar comfort become visible again: warm water, clean sheets, an open window." },
  { id: "gratitud-020", category: "gratitud", text: "Gratitude can sit beside disappointment; neither has to erase the other." },
  { id: "gratitud-021", category: "gratitud", text: "Remember one kindness that changed the temperature of an otherwise difficult day." },
  { id: "gratitud-022", category: "gratitud", text: "What supports you quietly may deserve more attention than what impresses you briefly." },
  { id: "gratitud-023", category: "gratitud", text: "Receive the good moment without asking it to justify everything that came before." },
  { id: "gratitud-024", category: "gratitud", text: "A name, a meal, a message, a safe return: let one specific thing be enough to feel grateful." },
  { id: "gratitud-025", category: "gratitud", text: "Notice what no longer hurts in the way it once did; healing can become familiar too." },
  { id: "gratitud-026", category: "gratitud", text: "The life you want is not only ahead of you; pieces of it may already be in the room." },
  { id: "gratitud-027", category: "gratitud", text: "Say thank you while the ordinary moment is happening, not only after it becomes a memory." },
  { id: "gratitud-028", category: "gratitud", text: "Name exactly what made this moment gentler; gratitude grows clearer in the details." },
  { id: "gratitud-029", category: "gratitud", text: "Someone once made room for you; carry that warmth into the room you offer others." },
  { id: "gratitud-030", category: "gratitud", text: "End the day by finding one thing that asked nothing from you and still offered comfort." },
  { id: "gratitud-031", category: "gratitud", text: "Notice the person who makes a routine task lighter simply by doing their part." },
  { id: "gratitud-032", category: "gratitud", text: "Before clearing the table, remember one thing that was shared around it." },
  { id: "gratitud-033", category: "gratitud", text: "A working key, a charged phone, a familiar route: quiet usefulness deserves notice." },
  { id: "gratitud-034", category: "gratitud", text: "Thank someone for a specific detail; precision can make appreciation feel more real." },
  { id: "gratitud-035", category: "gratitud", text: "Let the first sip, the open curtain, or the cool floor remind you that morning has arrived." },
  { id: "gratitud-036", category: "gratitud", text: "An ordinary skill you use without thinking was once something you had to learn." },
  { id: "gratitud-037", category: "gratitud", text: "Notice which burden did not arrive today; absence can sometimes be a quiet kindness." },
  { id: "gratitud-038", category: "gratitud", text: "A repaired object carries two gifts: its usefulness and someone's decision not to give up on it." },
  { id: "gratitud-039", category: "gratitud", text: "Give your attention to one sound that makes this place feel familiar." },
  { id: "gratitud-040", category: "gratitud", text: "Remember the people whose work reaches you through clean streets, safe food, or reliable light." },
  { id: "gratitud-041", category: "gratitud", text: "A plan that changed may still have brought you somewhere worth noticing." },
  { id: "gratitud-042", category: "gratitud", text: "Save one small detail from today before the larger events claim the whole story." },
  { id: "gratitud-043", category: "gratitud", text: "Appreciate the question that made you think, even if the answer is still forming." },
  { id: "gratitud-044", category: "gratitud", text: "The chance to try again can look ordinary until you remember it was not guaranteed." },
  { id: "gratitud-045", category: "gratitud", text: "Notice what your hands made easier today, from tying a shoe to preparing a meal." },
  { id: "gratitud-046", category: "gratitud", text: "A shared joke can be a brief shelter; enjoy it without asking it to solve anything." },
  { id: "gratitud-047", category: "gratitud", text: "There may be care hidden in a reminder, a packed bag, or a door someone holds open for you." },
  { id: "gratitud-048", category: "gratitud", text: "Honor the ordinary day that gave you enough room to breathe, work, and return home." },
  { id: "gratitud-049", category: "gratitud", text: "Something you once practiced carefully may now be helping you without asking for attention." },
  { id: "gratitud-050", category: "gratitud", text: "Let a familiar song return you to one good moment you had almost misplaced." },
  { id: "gratitud-051", category: "gratitud", text: "Thank the friend who sends the ordinary message that keeps the thread between you alive." },
  { id: "gratitud-052", category: "gratitud", text: "A useful mistake may leave you with better questions than the easy success did." },
  { id: "gratitud-053", category: "gratitud", text: "Notice the shade on a hot street, the bench on a long walk, the pause when you needed it." },
  { id: "gratitud-054", category: "gratitud", text: "Keep one object that reminds you how far an ordinary effort has carried you." },
  { id: "gratitud-055", category: "gratitud", text: "A meal can hold weather, work, memory, and care before it ever reaches the plate." },
  { id: "gratitud-056", category: "gratitud", text: "Appreciate the version of a problem that turned out to be smaller than you feared." },
  { id: "gratitud-057", category: "gratitud", text: "When someone remembers a detail about you, notice the attention that made it possible." },
  { id: "gratitud-058", category: "gratitud", text: "The ability to begin again this morning is worth noticing before the schedule takes over." },
  { id: "gratitud-059", category: "gratitud", text: "Look for the unnoticed handoff that helped your day continue smoothly." },
  { id: "gratitud-060", category: "gratitud", text: "Before sleep, choose one moment you would be glad to recognize if tomorrow resembled today." },
  { id: "valentia-001", category: "valentia", text: "Courage is not the absence of trembling; it is moving without giving fear the wheel." },
  { id: "valentia-002", category: "valentia", text: "Choose one safe, prepared action that gives the fear something real to respond to." },
  { id: "valentia-003", category: "valentia", text: "You do not need absolute certainty to make an honest decision." },
  { id: "valentia-004", category: "valentia", text: "What you avoid also takes up space; face it directly." },
  { id: "valentia-005", category: "valentia", text: "Dare to disappoint the expectations that were dimming your light." },
  { id: "valentia-006", category: "valentia", text: "Courage can also be a private decision that nobody ever applauds." },
  { id: "valentia-007", category: "valentia", text: "Fear can grow loud near an important choice; listen, then decide what is safe and true for you." },
  { id: "valentia-008", category: "valentia", text: "Do not confuse caution with hiding forever." },
  { id: "valentia-009", category: "valentia", text: "Try one manageable part of what once felt too large, and learn from what actually happens." },
  { id: "valentia-010", category: "valentia", text: "Your voice can tremble and still tell the truth." },
  { id: "valentia-011", category: "valentia", text: "Choosing yourself can feel frightening; take the step when it also respects your safety and values." },
  { id: "valentia-012", category: "valentia", text: "Sometimes growth means no longer negotiating with what makes you smaller." },
  { id: "valentia-013", category: "valentia", text: "Not every uncertainty is a warning; sometimes it is simply the edge of something new." },
  { id: "valentia-014", category: "valentia", text: "Before the task grows in your imagination, define one safe first step and prepare it." },
  { id: "valentia-015", category: "valentia", text: "Courage begins when you choose not to live only to avoid discomfort." },
  { id: "valentia-016", category: "valentia", text: "Courage can be quiet: staying in the room when the truth needs a voice." },
  { id: "valentia-017", category: "valentia", text: "You can listen to fear without letting it make every decision; check the facts and choose carefully." },
  { id: "valentia-018", category: "valentia", text: "An honest next step can feel uncomfortable; examine its consequences and choose with care." },
  { id: "valentia-019", category: "valentia", text: "Every boundary you voice makes clearer what you will and will not accept." },
  { id: "valentia-020", category: "valentia", text: "Sometimes courage means asking the question whose answer could change your plans." },
  { id: "valentia-021", category: "valentia", text: "You can step into the unknown without pretending that you are unafraid." },
  { id: "valentia-022", category: "valentia", text: "Some doors open only after you accept that you cannot see the next room." },
  { id: "valentia-023", category: "valentia", text: "Saying “I was wrong” can require more strength than continuing to defend yourself." },
  { id: "valentia-024", category: "valentia", text: "When a choice matters, waiting indefinitely is also a choice made for you." },
  { id: "valentia-025", category: "valentia", text: "Let your nervous hands begin; confidence can catch up with them later." },
  { id: "valentia-026", category: "valentia", text: "Protecting what matters sometimes means being misunderstood for a while." },
  { id: "valentia-027", category: "valentia", text: "You can explore what comes next before leaving what is familiar; courage also allows a careful transition." },
  { id: "valentia-028", category: "valentia", text: "When the situation is safe, courage may mean staying long enough to learn instead of fleeing the first discomfort." },
  { id: "valentia-029", category: "valentia", text: "Name what hurts clearly; vagueness gives fear too much room to grow." },
  { id: "valentia-030", category: "valentia", text: "A difficult truth becomes easier to live with once it finally has a voice." },
  { id: "valentia-031", category: "valentia", text: "Courage may begin by reading the difficult message slowly instead of imagining its contents." },
  { id: "valentia-032", category: "valentia", text: "Ask for the clarification you need before uncertainty writes the story for you." },
  { id: "valentia-033", category: "valentia", text: "Prepare carefully, then let preparation support the step rather than postpone it." },
  { id: "valentia-034", category: "valentia", text: "Admitting that you need time can be braver than offering an answer you do not trust." },
  { id: "valentia-035", category: "valentia", text: "Make the appointment that turns a private worry into something you can examine clearly." },
  { id: "valentia-036", category: "valentia", text: "A careful retreat can protect what matters; courage is not the same as refusing to reassess." },
  { id: "valentia-037", category: "valentia", text: "Name the condition under which you would be willing to try, then build toward it." },
  { id: "valentia-038", category: "valentia", text: "Let your first question be imperfect; a real conversation needs somewhere to begin." },
  { id: "valentia-039", category: "valentia", text: "Bring a trusted person when the important step feels too heavy to take alone." },
  { id: "valentia-040", category: "valentia", text: "Correct the record when silence would leave someone carrying a false version of you." },
  { id: "valentia-041", category: "valentia", text: "A brave plan includes an exit, a phone number, and enough information to choose safely." },
  { id: "valentia-042", category: "valentia", text: "Say the smaller truth first if it helps you find the words for the larger one." },
  { id: "valentia-043", category: "valentia", text: "Reconsider the overlooked opportunity by separating verified costs from unanswered questions." },
  { id: "valentia-044", category: "valentia", text: "Ask what can be tested in a small way before treating the choice as irreversible." },
  { id: "valentia-045", category: "valentia", text: "Let the pause before speaking gather your honesty, not bury it." },
  { id: "valentia-046", category: "valentia", text: "Changing direction after new evidence is a responsible act, not a failure of nerve." },
  { id: "valentia-047", category: "valentia", text: "Walk into the room knowing you may listen, ask questions, and decide later." },
  { id: "valentia-048", category: "valentia", text: "Keep one promise to speak when the moment is calm enough for the truth to be heard." },
  { id: "valentia-049", category: "valentia", text: "Being the first to soften your tone does not require surrendering your point." },
  { id: "valentia-050", category: "valentia", text: "Risk deserves research; informed courage leaves fewer decisions to panic." },
  { id: "valentia-051", category: "valentia", text: "Show the early draft to one thoughtful person instead of hiding it from everyone." },
  { id: "valentia-052", category: "valentia", text: "The next step may be to document what happened before deciding how to respond." },
  { id: "valentia-053", category: "valentia", text: "Ask directly for what you need and leave the other person free to answer honestly." },
  { id: "valentia-054", category: "valentia", text: "Start the conversation with what you observed, not with the verdict fear prepared." },
  { id: "valentia-055", category: "valentia", text: "Leave room to be surprised; not every difficult encounter follows the old script." },
  { id: "valentia-056", category: "valentia", text: "If the room feels unsafe, choosing distance can be the courageous decision." },
  { id: "valentia-057", category: "valentia", text: "Put the question on paper first; written words can help courage find its shape." },
  { id: "valentia-058", category: "valentia", text: "Take responsibility for your part without volunteering to carry what belongs to others." },
  { id: "valentia-059", category: "valentia", text: "Begin before you feel impressive; sincerity is enough for a first attempt." },
  { id: "valentia-060", category: "valentia", text: "After the difficult step, give yourself time to settle before judging how you handled it." },
  { id: "habitos-001", category: "habitos", text: "A good habit does not need to impress; it needs to be repeated." },
  { id: "habitos-002", category: "habitos", text: "Lower the setup effort until beginning feels clear, then let the routine grow only if it fits." },
  { id: "habitos-003", category: "habitos", text: "A practical routine can keep one useful action available on days when motivation changes." },
  { id: "habitos-004", category: "habitos", text: "Do not build from guilt; build from a gentler kind of order." },
  { id: "habitos-005", category: "habitos", text: "A habit begins when you stop deciding about it every day." },
  { id: "habitos-006", category: "habitos", text: "One small repetition can begin a new identity." },
  { id: "habitos-007", category: "habitos", text: "What you prepare at night takes care of you in the morning." },
  { id: "habitos-008", category: "habitos", text: "Keep the equipment in working order; a small repair can protect tomorrow's routine." },
  { id: "habitos-009", category: "habitos", text: "Returning to a habit after missing it is part of the habit too." },
  { id: "habitos-010", category: "habitos", text: "When helpful choices require less negotiation, attention remains for the rest of the day." },
  { id: "habitos-011", category: "habitos", text: "Begin with a short, complete action that leaves a clear place to continue tomorrow." },
  { id: "habitos-012", category: "habitos", text: "Remove one unnecessary step from the routine and notice whether returning becomes easier." },
  { id: "habitos-013", category: "habitos", text: "A useful system makes starting easier and returning after a miss less costly." },
  { id: "habitos-014", category: "habitos", text: "You do not need to change your whole life; begin with the first action of the day." },
  { id: "habitos-015", category: "habitos", text: "Consistency works better when designed than when forced." },
  { id: "habitos-016", category: "habitos", text: "A useful routine makes room for bad days instead of collapsing with them." },
  { id: "habitos-017", category: "habitos", text: "Leave the first step where your tired self can find it without much thought." },
  { id: "habitos-018", category: "habitos", text: "Measure how quickly you return, not how many days you managed to be flawless." },
  { id: "habitos-019", category: "habitos", text: "A well-prepared environment makes the helpful choice easier when you are tired." },
  { id: "habitos-020", category: "habitos", text: "Tie the action to a steady cue, and remembering will require less effort." },
  { id: "habitos-021", category: "habitos", text: "If a habit only works when you feel inspired, it still needs a sturdier foundation." },
  { id: "habitos-022", category: "habitos", text: "Leave visible evidence of what you completed; progress needs a memory too." },
  { id: "habitos-023", category: "habitos", text: "End the day in a way that makes tomorrow easier to begin." },
  { id: "habitos-024", category: "habitos", text: "Protect a minimum version of the habit for days when you cannot give more." },
  { id: "habitos-025", category: "habitos", text: "Habits become more sustainable when rest is built into their design." },
  { id: "habitos-026", category: "habitos", text: "Tell one supportive person what you plan to repeat, and ask for encouragement rather than surveillance." },
  { id: "habitos-027", category: "habitos", text: "Missing once is an event; returning at the next opportunity is a decision." },
  { id: "habitos-028", category: "habitos", text: "Improve the path of the habit before blaming yourself for walking it poorly." },
  { id: "habitos-029", category: "habitos", text: "The right pace works beyond perfect weeks; it also survives the busy ones." },
  { id: "habitos-030", category: "habitos", text: "Choose a routine you can pause, resume, and keep shaping." },
  { id: "habitos-031", category: "habitos", text: "Place the book on the chair tonight so tomorrow's first page already has an invitation." },
  { id: "habitos-032", category: "habitos", text: "Write down the smallest version of the routine before a busy day decides it for you." },
  { id: "habitos-033", category: "habitos", text: "A clear stopping point makes tomorrow's return easier than working until you are empty." },
  { id: "habitos-034", category: "habitos", text: "Keep the tools for a helpful habit closer than the distractions competing with it." },
  { id: "habitos-035", category: "habitos", text: "Choose a cue you already notice: the kettle, the commute, or the closing of a laptop." },
  { id: "habitos-036", category: "habitos", text: "Track the action long enough to learn its pattern, then keep only the record that helps." },
  { id: "habitos-037", category: "habitos", text: "Prepare for the predictable obstacle before asking willpower to solve it again." },
  { id: "habitos-038", category: "habitos", text: "A routine that takes fifteen minutes needs a real place in the calendar, not a vague intention." },
  { id: "habitos-039", category: "habitos", text: "Reduce the distance between deciding and beginning: open the file, fill the bottle, set out the shoes." },
  { id: "habitos-040", category: "habitos", text: "Review the week without grading your character; you are adjusting a system, not judging a person." },
  { id: "habitos-041", category: "habitos", text: "If the routine keeps failing at the same hour, move the hour before increasing the effort." },
  { id: "habitos-042", category: "habitos", text: "Pair the task you postpone with a beginning you enjoy, such as music or a favorite place." },
  { id: "habitos-043", category: "habitos", text: "When you stop midway, arrange the materials in the order you will need them next." },
  { id: "habitos-044", category: "habitos", text: "A habit can shrink during a difficult week without disappearing from your life." },
  { id: "habitos-045", category: "habitos", text: "Change the place or format when boredom, rather than difficulty, is what interrupts the routine." },
  { id: "habitos-046", category: "habitos", text: "Store each object where the action begins, not where the room looks most impressive." },
  { id: "habitos-047", category: "habitos", text: "When two habits compete, protect the one that makes the other easier tomorrow." },
  { id: "habitos-048", category: "habitos", text: "Use reminders as a bridge while the routine is new, then remove the ones that become noise." },
  { id: "habitos-049", category: "habitos", text: "Make the restart specific: name the day, the place, and the first visible action." },
  { id: "habitos-050", category: "habitos", text: "A visible calendar can reveal whether the plan respects the life you actually have." },
  { id: "habitos-051", category: "habitos", text: "Place a small pleasure near the finish so the routine ends with a reason to return." },
  { id: "habitos-052", category: "habitos", text: "Before adding a new routine, decide which old demand will make room for it." },
  { id: "habitos-053", category: "habitos", text: "A habit that fits a demanding day has a better chance of lasting through a busy month." },
  { id: "habitos-054", category: "habitos", text: "Use a missed day to inspect the setup, not to rehearse a speech about discipline." },
  { id: "habitos-055", category: "habitos", text: "One prepared meal, cleared desk, or scheduled walk can make a helpful choice more likely." },
  { id: "habitos-056", category: "habitos", text: "Let the routine end early sometimes; leaving with energy can protect the next return." },
  { id: "habitos-057", category: "habitos", text: "Name the friction precisely: time, tools, place, energy, or an unclear first step." },
  { id: "habitos-058", category: "habitos", text: "A weekly reset can be ten quiet minutes spent returning useful things to their places." },
  { id: "habitos-059", category: "habitos", text: "If the plan depends on remembering, place the reminder where the decision actually happens." },
  { id: "habitos-060", category: "habitos", text: "Choose the next repetition before celebrating this one; continuity likes a clear invitation." },
  { id: "creatividad-001", category: "creatividad", text: "An idea does not always arrive shining; sometimes it arrives awkward and asks for care." },
  { id: "creatividad-002", category: "creatividad", text: "Create before judging; the editor can wait until something exists." },
  { id: "creatividad-003", category: "creatividad", text: "Keep a place for sudden ideas, but give the quiet ones enough time to develop." },
  { id: "creatividad-004", category: "creatividad", text: "Do not force originality; seek precise honesty instead." },
  { id: "creatividad-005", category: "creatividad", text: "A bad first version is a doorway, not a sentence." },
  { id: "creatividad-006", category: "creatividad", text: "Creativity needs play, but it also needs to finish something." },
  { id: "creatividad-007", category: "creatividad", text: "Look at the familiar from another angle and you already have material." },
  { id: "creatividad-008", category: "creatividad", text: "Not everything you make must please everyone to deserve to exist." },
  { id: "creatividad-009", category: "creatividad", text: "Creative clarity comes from working, not from waiting for a perfect sign." },
  { id: "creatividad-010", category: "creatividad", text: "Make a small version of the idea before fear talks you out of it." },
  { id: "creatividad-011", category: "creatividad", text: "Your voice becomes clearer by using it, not by comparing it to others." },
  { id: "creatividad-012", category: "creatividad", text: "Follow a question slightly beyond what seems reasonable; new ideas often wait there." },
  { id: "creatividad-013", category: "creatividad", text: "Let something be simple if simplicity makes it true." },
  { id: "creatividad-014", category: "creatividad", text: "The blank page loses power when you add one imperfect sentence." },
  { id: "creatividad-015", category: "creatividad", text: "Creating also means trusting that you can improve what is barely beginning today." },
  { id: "creatividad-016", category: "creatividad", text: "Ask better questions; interesting work often begins where the obvious answer fails." },
  { id: "creatividad-017", category: "creatividad", text: "Save the strange fragments; not every idea arrives with instructions." },
  { id: "creatividad-018", category: "creatividad", text: "Sometimes a creative block is too much noise; clear one corner and look again." },
  { id: "creatividad-019", category: "creatividad", text: "Finish a sketch to discover what the idea was actually trying to say." },
  { id: "creatividad-020", category: "creatividad", text: "Borrow a structure, not a voice; influences can serve as scaffolding." },
  { id: "creatividad-021", category: "creatividad", text: "A well-chosen limit can give the project a shape that freedom could not find." },
  { id: "creatividad-022", category: "creatividad", text: "Let curiosity walk a few steps before demanding that it be useful." },
  { id: "creatividad-023", category: "creatividad", text: "Notice what irritates you; it may point toward a question you have not finished." },
  { id: "creatividad-024", category: "creatividad", text: "Work that surprises its maker has a chance of surprising someone else." },
  { id: "creatividad-025", category: "creatividad", text: "When an idea gets stuck, change tools; another form may reveal what was missing." },
  { id: "creatividad-026", category: "creatividad", text: "Protect early work from a premature audience; first it needs to learn how to stand." },
  { id: "creatividad-027", category: "creatividad", text: "Originality appears when ordinary observations meet in a combination only you noticed." },
  { id: "creatividad-028", category: "creatividad", text: "Make room for boredom; a mind without instructions begins finding its own paths." },
  { id: "creatividad-029", category: "creatividad", text: "Every choice closes possibilities, and that is exactly how a piece takes shape." },
  { id: "creatividad-030", category: "creatividad", text: "Stop polishing the sentence the project no longer needs, and hear what it asks for now." },
  { id: "creatividad-031", category: "creatividad", text: "An unfinished thought can become useful when you give it a shape another person can enter." },
  { id: "creatividad-032", category: "creatividad", text: "Collect the detail that catches your eye; its purpose can wait until later." },
  { id: "creatividad-033", category: "creatividad", text: "Begin with the tension you cannot explain yet; it may be the most alive part of the work." },
  { id: "creatividad-034", category: "creatividad", text: "A simple creative routine protects attention from having to negotiate with every mood." },
  { id: "creatividad-035", category: "creatividad", text: "Read the draft aloud; your ear may catch what your eyes learned to overlook." },
  { id: "creatividad-036", category: "creatividad", text: "One exact detail can carry more feeling than a paragraph of impressive adjectives." },
  { id: "creatividad-037", category: "creatividad", text: "Finish a piece before turning it into a verdict about your talent." },
  { id: "creatividad-038", category: "creatividad", text: "Question the rule everyone stopped noticing; there may be a fresh path underneath it." },
  { id: "creatividad-039", category: "creatividad", text: "Gather freely at first, then choose firmly; discovery and direction need different moments." },
  { id: "creatividad-040", category: "creatividad", text: "Alternate between making and looking; distance helps you see what effort can hide." },
  { id: "creatividad-041", category: "creatividad", text: "The part that resists you may be pointing to a decision the project still needs." },
  { id: "creatividad-042", category: "creatividad", text: "Leave one question open long enough for the work to answer it in its own language." },
  { id: "creatividad-043", category: "creatividad", text: "An experiment that fails clearly still teaches you how the material wants to behave." },
  { id: "creatividad-044", category: "creatividad", text: "Change one thing in your surroundings and notice which thoughts become easier to reach." },
  { id: "creatividad-045", category: "creatividad", text: "If a beautiful part weakens the whole, save it elsewhere and let the work breathe." },
  { id: "creatividad-046", category: "creatividad", text: "A temporary title can act as a compass without becoming the final destination." },
  { id: "creatividad-047", category: "creatividad", text: "A story becomes vivid when each important choice changes what can happen next." },
  { id: "creatividad-048", category: "creatividad", text: "Specificity is a quiet kind of courage: it lets the work risk being truly seen." },
  { id: "creatividad-049", category: "creatividad", text: "Picture one attentive person encountering the work; a clear audience can sharpen your choices." },
  { id: "creatividad-050", category: "creatividad", text: "Give research a boundary so that learning eventually turns into making." },
  { id: "creatividad-051", category: "creatividad", text: "When thought circles the same answer, a short walk can change the shape of the question." },
  { id: "creatividad-052", category: "creatividad", text: "Keep the tools for beginning close enough that a small impulse can become a real attempt." },
  { id: "creatividad-053", category: "creatividad", text: "Before rejecting what feels unfamiliar, ask whether it is wrong or simply new to you." },
  { id: "creatividad-054", category: "creatividad", text: "A repeated image can become a thread that helps separate pieces feel connected." },
  { id: "creatividad-055", category: "creatividad", text: "Name the problem in plain language; mystery is easier to explore once confusion has a boundary." },
  { id: "creatividad-056", category: "creatividad", text: "Follow the choice that makes the work more itself, even when it makes the work less familiar." },
  { id: "creatividad-057", category: "creatividad", text: "A missing resource can invite a solution that abundance would never have suggested." },
  { id: "creatividad-058", category: "creatividad", text: "Let the draft be understated when that feels honest; not every piece needs to announce its importance." },
  { id: "creatividad-059", category: "creatividad", text: "Revision can make the path clearer without removing every surprise along the way." },
  { id: "creatividad-060", category: "creatividad", text: "End a session with the next move visible; tomorrow will have somewhere to begin." },
  { id: "resiliencia-001", category: "resiliencia", text: "Not everything that breaks you gets to decide how you rebuild." },
  { id: "resiliencia-002", category: "resiliencia", text: "Surviving a difficult day is also a form of progress." },
  { id: "resiliencia-003", category: "resiliencia", text: "Strength is not always visible; sometimes it is simply continuing to care for yourself." },
  { id: "resiliencia-004", category: "resiliencia", text: "Tiredness can change what is reasonable today without deciding what will be possible later." },
  { id: "resiliencia-005", category: "resiliencia", text: "What happened is part of your story; it does not have to become your boundary." },
  { id: "resiliencia-006", category: "resiliencia", text: "Recovery does not require returning unchanged; it may mean returning with a clearer sense of yourself." },
  { id: "resiliencia-007", category: "resiliencia", text: "What fills your whole view today does not have to fill your entire future." },
  { id: "resiliencia-008", category: "resiliencia", text: "Hope is sometimes practical: eat, sleep, ask for help, try again tomorrow." },
  { id: "resiliencia-009", category: "resiliencia", text: "Do not minimize what you carried just because you learned to walk with it." },
  { id: "resiliencia-010", category: "resiliencia", text: "Each time you rise again, you negotiate less with defeat." },
  { id: "resiliencia-011", category: "resiliencia", text: "There is dignity in rebuilding yourself slowly too." },
  { id: "resiliencia-012", category: "resiliencia", text: "You do not have to turn pain into a lesson before allowing yourself to feel it." },
  { id: "resiliencia-013", category: "resiliencia", text: "Hardship did not make you less; it showed which parts need tenderness." },
  { id: "resiliencia-014", category: "resiliencia", text: "If all you can do today is hold yourself together, that still counts." },
  { id: "resiliencia-015", category: "resiliencia", text: "Trusting life again can begin with one small action." },
  { id: "resiliencia-016", category: "resiliencia", text: "Give a hard change time to become familiar before deciding everything it has taken from you." },
  { id: "resiliencia-017", category: "resiliencia", text: "One hard day after a good week does not erase everything that week gave you." },
  { id: "resiliencia-018", category: "resiliencia", text: "Rest can be part of repair without becoming a retreat." },
  { id: "resiliencia-019", category: "resiliencia", text: "What once sustained you may need updating; resilience includes changing your tools." },
  { id: "resiliencia-020", category: "resiliencia", text: "Ask for company before turning what you carry into proof of your strength." },
  { id: "resiliencia-021", category: "resiliencia", text: "You can grieve what was lost without losing interest in what still remains." },
  { id: "resiliencia-022", category: "resiliencia", text: "A difficult memory can remain part of your story without taking up the whole room." },
  { id: "resiliencia-023", category: "resiliencia", text: "You do not need to thank the wound to feel proud of how you cared for yourself." },
  { id: "resiliencia-024", category: "resiliencia", text: "In some seasons, progress means keeping the essential things safe." },
  { id: "resiliencia-025", category: "resiliencia", text: "Strength can mean changing pace before your body forces you to stop." },
  { id: "resiliencia-026", category: "resiliencia", text: "You survived not because nothing affected you, but because you kept adapting." },
  { id: "resiliencia-027", category: "resiliencia", text: "When old pain returns, meet it with the resources you have today." },
  { id: "resiliencia-028", category: "resiliencia", text: "A setback offers information about the terrain, not a verdict on your destination." },
  { id: "resiliencia-029", category: "resiliencia", text: "Begin again from where you are, not from where you think you should already be." },
  { id: "resiliencia-030", category: "resiliencia", text: "The life you rebuild does not need to resemble the old one to remain yours." },
  { id: "resiliencia-031", category: "resiliencia", text: "A plan can bend without becoming a failure; adjust it to the ground you actually have." },
  { id: "resiliencia-032", category: "resiliencia", text: "When the whole task feels heavy, protect the smallest part that still keeps it moving." },
  { id: "resiliencia-033", category: "resiliencia", text: "You do not need the old version of your strength for the next part of the journey." },
  { id: "resiliencia-034", category: "resiliencia", text: "Keep one ordinary promise to yourself; steadiness often returns through familiar doors." },
  { id: "resiliencia-035", category: "resiliencia", text: "A changed route can still lead toward what matters, even if the map looks different now." },
  { id: "resiliencia-036", category: "resiliencia", text: "Let a setback revise your method without letting it define your worth." },
  { id: "resiliencia-037", category: "resiliencia", text: "Accepting a steady hand does not erase the steps you have taken for yourself." },
  { id: "resiliencia-038", category: "resiliencia", text: "Count what you preserved during the hard season, not only what you could not complete." },
  { id: "resiliencia-039", category: "resiliencia", text: "Lowering today's load does not require lowering your hopes for the future." },
  { id: "resiliencia-040", category: "resiliencia", text: "The next useful step may be smaller than your pride prefers and wiser than it expects." },
  { id: "resiliencia-041", category: "resiliencia", text: "Notice the choices you still have; even a narrow path can contain more than one direction." },
  { id: "resiliencia-042", category: "resiliencia", text: "Let patience be active: prepare, observe, and move when the ground is ready." },
  { id: "resiliencia-043", category: "resiliencia", text: "What you learned under pressure can remain useful without keeping you under constant strain." },
  { id: "resiliencia-044", category: "resiliencia", text: "Make room for a good hour inside a difficult week; neither experience cancels the other." },
  { id: "resiliencia-045", category: "resiliencia", text: "There is no shame in rebuilding with simpler materials than you once imagined." },
  { id: "resiliencia-046", category: "resiliencia", text: "When certainty is unavailable, choose the next action that leaves you more options." },
  { id: "resiliencia-047", category: "resiliencia", text: "A boundary can protect the part of you that is still learning how to trust again." },
  { id: "resiliencia-048", category: "resiliencia", text: "Do not measure a quiet recovery by the pace of someone else's visible success." },
  { id: "resiliencia-049", category: "resiliencia", text: "Some days build momentum; others keep the door open. Both can serve the journey." },
  { id: "resiliencia-050", category: "resiliencia", text: "Carry forward the wisdom, not every defense that once helped you endure." },
  { id: "resiliencia-051", category: "resiliencia", text: "You are allowed to solve today's version of the problem instead of every future version." },
  { id: "resiliencia-052", category: "resiliencia", text: "A careful pause can keep a hard moment from choosing your next several moves." },
  { id: "resiliencia-053", category: "resiliencia", text: "Notice which small choices kept the day from getting harder; resilience often works quietly." },
  { id: "resiliencia-054", category: "resiliencia", text: "Missing what was familiar does not prevent you from choosing what better fits the future you want." },
  { id: "resiliencia-055", category: "resiliencia", text: "When progress becomes hard to see, compare the choices you make now with the ones you once had." },
  { id: "resiliencia-056", category: "resiliencia", text: "Repair one reachable corner; order can return without arriving everywhere at once." },
  { id: "resiliencia-057", category: "resiliencia", text: "Your pace can change with the weather without changing the direction you value." },
  { id: "resiliencia-058", category: "resiliencia", text: "Leave some room in the plan for being human; endurance grows from honest expectations." },
  { id: "resiliencia-059", category: "resiliencia", text: "A difficult chapter can deserve a gentle ending before the next one begins." },
  { id: "resiliencia-060", category: "resiliencia", text: "Name what remains possible today; clarity can turn a difficult situation into a workable starting point." },
  { id: "relaciones-001", category: "relaciones", text: "Listening well is a quiet way of saying: you matter." },
  { id: "relaciones-002", category: "relaciones", text: "Do not confuse peace with always staying silent." },
  { id: "relaciones-003", category: "relaciones", text: "Healthy love does not ask you to disappear so someone else can feel comfortable." },
  { id: "relaciones-004", category: "relaciones", text: "One honest conversation in time can prevent a great deal of distance." },
  { id: "relaciones-005", category: "relaciones", text: "Give the people you love some attention that does not have to compete with a screen." },
  { id: "relaciones-006", category: "relaciones", text: "A clear boundary gives a relationship room to continue without quiet resentment." },
  { id: "relaciones-007", category: "relaciones", text: "Not every relationship deserves the same access to your energy." },
  { id: "relaciones-008", category: "relaciones", text: "Appreciate the people who make it easy to be yourself." },
  { id: "relaciones-009", category: "relaciones", text: "Closeness grows through small acts repeated over time, not through isolated grand gestures." },
  { id: "relaciones-010", category: "relaciones", text: "You can love someone and still need space." },
  { id: "relaciones-011", category: "relaciones", text: "Intensity and closeness are not the same; notice whether the bond also makes room for steadiness." },
  { id: "relaciones-012", category: "relaciones", text: "Trust grows where words and actions align." },
  { id: "relaciones-013", category: "relaciones", text: "Care for your relationships, but do not use your peace as currency." },
  { id: "relaciones-014", category: "relaciones", text: "Make room for people who let you rest without asking you to become someone else." },
  { id: "relaciones-015", category: "relaciones", text: "A real apology does not try to win; it tries to repair." },
  { id: "relaciones-016", category: "relaciones", text: "Being understood begins with the risk of saying what you truly mean." },
  { id: "relaciones-017", category: "relaciones", text: "Caring well means staying curious about who someone is now, not only remembering who they were." },
  { id: "relaciones-018", category: "relaciones", text: "A healthy bond can hold differences without turning them into threats." },
  { id: "relaciones-019", category: "relaciones", text: "Ask before assuming; imagination is a poor substitute for a conversation." },
  { id: "relaciones-020", category: "relaciones", text: "Reliability is a form of affection that also shows up on the calendar." },
  { id: "relaciones-021", category: "relaciones", text: "You can be kind without making yourself available at every hour." },
  { id: "relaciones-022", category: "relaciones", text: "Repair begins when the impact matters more than defending the intention." },
  { id: "relaciones-023", category: "relaciones", text: "Friendship needs real invitations too, not only quiet affection." },
  { id: "relaciones-024", category: "relaciones", text: "People change; loving who they are now requires updating how you see them." },
  { id: "relaciones-025", category: "relaciones", text: "Silence can be companionship when nobody pressures you to fill it." },
  { id: "relaciones-026", category: "relaciones", text: "Conflict handled with respect can make closeness more honest." },
  { id: "relaciones-027", category: "relaciones", text: "Do not test people in secret; tell them clearly what you need." },
  { id: "relaciones-028", category: "relaciones", text: "Reciprocity does not need to be identical, but it should feel mutual." },
  { id: "relaciones-029", category: "relaciones", text: "Celebrate the ordinary wins of those you love; much of life happens there." },
  { id: "relaciones-030", category: "relaciones", text: "Leaving room for a “no” makes every “yes” in the relationship more honest." },
  { id: "relaciones-031", category: "relaciones", text: "Notice how the people you love receive care; good intentions become useful through attention." },
  { id: "relaciones-032", category: "relaciones", text: "A small message sent today can keep affection from becoming only a good intention." },
  { id: "relaciones-033", category: "relaciones", text: "Listen for the need beneath the clumsy sentence without pretending the words caused no harm." },
  { id: "relaciones-034", category: "relaciones", text: "Tell people what you appreciate while the ordinary moment is still happening." },
  { id: "relaciones-035", category: "relaciones", text: "Connection deepens when both people can bring unfinished thoughts without being rushed." },
  { id: "relaciones-036", category: "relaciones", text: "Before solving someone's problem, find out whether they want ideas, help, or simply company." },
  { id: "relaciones-037", category: "relaciones", text: "When plans change, say so early; consideration includes the time another person set aside." },
  { id: "relaciones-038", category: "relaciones", text: "Disagreement does not require turning the other person's character into the argument." },
  { id: "relaciones-039", category: "relaciones", text: "Share the small context; people cannot understand a story they are never allowed to hear." },
  { id: "relaciones-040", category: "relaciones", text: "Let affection become practical: remember the date, bring the water, make the call." },
  { id: "relaciones-041", category: "relaciones", text: "Remembering a small preference can make someone feel met rather than managed." },
  { id: "relaciones-042", category: "relaciones", text: "Do not make closeness prove itself through constant access; trust can include breathing room." },
  { id: "relaciones-043", category: "relaciones", text: "When you misunderstand, return with curiosity before returning with a defense." },
  { id: "relaciones-044", category: "relaciones", text: "A friendship can change shape without losing meaning; ask what connection fits this season." },
  { id: "relaciones-045", category: "relaciones", text: "Someone can care differently from you without caring less; notice patterns before making assumptions." },
  { id: "relaciones-046", category: "relaciones", text: "A difficult truth can be delivered without using sharpness as proof of honesty." },
  { id: "relaciones-047", category: "relaciones", text: "Notice who asks a second question; attention often reveals care more clearly than advice." },
  { id: "relaciones-048", category: "relaciones", text: "Give people a chance to correct a mistake, but let repeated patterns inform your trust." },
  { id: "relaciones-049", category: "relaciones", text: "Closeness is safer when no one has to guess which version of the rules applies today." },
  { id: "relaciones-050", category: "relaciones", text: "If the conversation matters, choose a place where neither person has to compete with the noise." },
  { id: "relaciones-051", category: "relaciones", text: "Respect the answer you invited, especially when it is not the one you hoped to hear." },
  { id: "relaciones-052", category: "relaciones", text: "A thoughtful check-in can say “I remember” without demanding a performance in return." },
  { id: "relaciones-053", category: "relaciones", text: "Let a new person reveal who they are before assigning them a role from your past." },
  { id: "relaciones-054", category: "relaciones", text: "In conflict, speak to the person in the room, not to an audience you imagine agreeing with you." },
  { id: "relaciones-055", category: "relaciones", text: "Shared work can create closeness too; not every meaningful exchange happens face to face." },
  { id: "relaciones-056", category: "relaciones", text: "Ask before sharing someone else's story; trust includes stewardship of what you were told." },
  { id: "relaciones-057", category: "relaciones", text: "Relationships need updates; what felt supportive last year may need a new conversation now." },
  { id: "relaciones-058", category: "relaciones", text: "In a group, notice who has not found a way into the conversation; welcome can be an action." },
  { id: "relaciones-059", category: "relaciones", text: "Leave space between the question and your reply; understanding sometimes arrives in the pause." },
  { id: "relaciones-060", category: "relaciones", text: "A good bond makes room for two full lives, not one life orbiting the other." },
  { id: "energia-001", category: "energia", text: "Do not plan your day as though your energy were infinite." },
  { id: "energia-002", category: "energia", text: "Protect some energy before you need it; not every reserve has to reach zero." },
  { id: "energia-003", category: "energia", text: "First do what requires your best, not what can survive on your leftovers." },
  { id: "energia-004", category: "energia", text: "Resting in time is also a productive decision." },
  { id: "energia-005", category: "energia", text: "If everything irritates you, perhaps you need a pause rather than an answer." },
  { id: "energia-006", category: "energia", text: "Notice early signs that your pace is becoming hard to sustain, and leave room to adjust it." },
  { id: "energia-007", category: "energia", text: "Do not fill every gap; open space works in your favor too." },
  { id: "energia-008", category: "energia", text: "Mornings are better when they do not begin with the whole world coming through a screen." },
  { id: "energia-009", category: "energia", text: "Protect the first hour; it often sets the tone for many more." },
  { id: "energia-010", category: "energia", text: "Less excess, more rhythm: that is how you sustain what truly matters." },
  { id: "energia-011", category: "energia", text: "A crowded schedule can hide whether any of its work still matters to you." },
  { id: "energia-012", category: "energia", text: "A glass of water, an open window, and five minutes can change how your whole day feels." },
  { id: "energia-013", category: "energia", text: "If your attention is fading, notice whether your body has been asking for care." },
  { id: "energia-014", category: "energia", text: "Choose one thing that restores your energy instead of another that only consumes it." },
  { id: "energia-015", category: "energia", text: "Ambition that never rests eventually begins to resemble punishment." },
  { id: "energia-016", category: "energia", text: "Your day needs margins; without them, every surprise becomes an emergency." },
  { id: "energia-017", category: "energia", text: "Use your clearest hours to create, and leave routine tasks for slower moments." },
  { id: "energia-018", category: "energia", text: "Before judging the whole day, change one small condition and notice whether the next hour feels different." },
  { id: "energia-019", category: "energia", text: "Some kinds of tiredness ask for sleep; others ask for company, fresh air, or a change of scene." },
  { id: "energia-020", category: "energia", text: "Stop before you are empty so tomorrow does not have to pay the full cost." },
  { id: "energia-021", category: "energia", text: "Interest can awaken your energy, but your body still needs fuel." },
  { id: "energia-022", category: "energia", text: "Remove one source of noise today and notice what regains room inside you." },
  { id: "energia-023", category: "energia", text: "Recovery is not a reward for reaching your limit; it is part of a sustainable rhythm." },
  { id: "energia-024", category: "energia", text: "Notice which conversations leave you clearer and which scatter you for hours." },
  { id: "energia-025", category: "energia", text: "A slower morning can prepare a far more useful afternoon." },
  { id: "energia-026", category: "energia", text: "Place demanding work near the hours when your attention naturally wakes up." },
  { id: "energia-027", category: "energia", text: "Breaks work better before your concentration disappears completely." },
  { id: "energia-028", category: "energia", text: "Protect the transition between work and rest; your mind needs to feel the difference." },
  { id: "energia-029", category: "energia", text: "Constant stimulation can hide exhaustion without ever repairing it." },
  { id: "energia-030", category: "energia", text: "Do not spend tomorrow’s energy just to prove you could finish everything today." },
  { id: "energia-031", category: "energia", text: "Put recovery beside effort on the calendar; what has no place is easy to postpone." },
  { id: "energia-032", category: "energia", text: "A shorter list can protect enough attention to do the important work well." },
  { id: "energia-033", category: "energia", text: "Match your surroundings to the energy the task needs; some work benefits from quiet, some from movement." },
  { id: "energia-034", category: "energia", text: "Save easy decisions for tired hours and protect clear thinking for choices that matter." },
  { id: "energia-035", category: "energia", text: "The task may need less force and a better starting point." },
  { id: "energia-036", category: "energia", text: "Reduce the number of open loops; unfinished decisions quietly ask for attention." },
  { id: "energia-037", category: "energia", text: "A useful rhythm includes moments that do not need to produce anything." },
  { id: "energia-038", category: "energia", text: "If the day begins late, redesign what remains instead of compressing the original plan." },
  { id: "energia-039", category: "energia", text: "Keep one part of the evening free from tomorrow; anticipation can consume rest before work begins." },
  { id: "energia-040", category: "energia", text: "Group small errands when you can; constant switching makes each one cost more attention." },
  { id: "energia-041", category: "energia", text: "Before adding motivation, remove one obstacle that makes beginning unnecessarily expensive." },
  { id: "energia-042", category: "energia", text: "A calm start can be more useful than borrowing urgency from a deadline that is still far away." },
  { id: "energia-043", category: "energia", text: "Make the next action obvious enough that beginning does not require a fresh debate." },
  { id: "energia-044", category: "energia", text: "When a commitment repeats, count its setup and recovery time, not only its scheduled hour." },
  { id: "energia-045", category: "energia", text: "Not every low-energy hour needs fixing; some simply need a gentler kind of task." },
  { id: "energia-046", category: "energia", text: "Let recurring tasks have recurring places; fewer decisions can leave more attention available." },
  { id: "energia-047", category: "energia", text: "Notice which commitments energize you after effort and which only leave you depleted." },
  { id: "energia-048", category: "energia", text: "Protect the time before an important task from decisions that can wait." },
  { id: "energia-049", category: "energia", text: "Make stopping part of the plan; otherwise every task will try to decide its own ending." },
  { id: "energia-050", category: "energia", text: "A few minutes of preparation can turn tomorrow's first step into an easier invitation." },
  { id: "energia-051", category: "energia", text: "Some momentum comes from removing, not adding: one tab, one meeting, one unnecessary promise." },
  { id: "energia-052", category: "energia", text: "Match the size of the effort to the importance of the outcome, not to the noise around it." },
  { id: "energia-053", category: "energia", text: "A day with one clear priority asks less of your attention than a day with ten equal alarms." },
  { id: "energia-054", category: "energia", text: "When everything feels urgent, identify what would still matter if the noise became quiet." },
  { id: "energia-055", category: "energia", text: "Protect an unhurried meal from becoming another pause filled with obligations." },
  { id: "energia-056", category: "energia", text: "Reserve a short block with no incoming messages; uninterrupted attention can feel lighter than haste." },
  { id: "energia-057", category: "energia", text: "The space after finishing belongs to you before it belongs to the next demand." },
  { id: "energia-058", category: "energia", text: "Build a day you can repeat, not one that only looks admirable from a distance." },
  { id: "energia-059", category: "energia", text: "Notice when effort stops improving the result; more time is not always more care." },
  { id: "energia-060", category: "energia", text: "Let enough be a deliberate choice sometimes, not an apology for what remains undone." },
];
